## 4. Full Minimal Example (Vite/React-style)

```js
// main.js ---------------------------------------------------------
import 'maplibre-gl/dist/maplibre-gl.css';
import '@mapbox/mapbox-gl-draw/dist/mapbox-gl-draw.css';
import '@maplibre/maplibre-gl-geocoder/dist/maplibre-gl-geocoder.css';

import MapLibreGL from 'maplibre-gl';
import MapboxDraw from '@mapbox/mapbox-gl-draw';
import MapLibreGeocoder from '@maplibre/maplibre-gl-geocoder';

const map = new MapLibreGL.Map({
  container: 'map',
  style: 'https://demotiles.maplibre.org/style.json',
  center: [-122.447303, 37.753574],
  zoom: 12,
});

const draw = new MapboxDraw({
  displayControlsDefault: false,
  controls: { polygon: true, line_string: true, trash: true },
});
map.addControl(draw);

const geocoder = new MapLibreGeocoder({
  // Use Mapbox token or any other service
  accessToken: 'YOUR_MAPBOX_TOKEN',
  maplibregl: MapLibreGL,
  placeholder: 'Search…',
});
map.addControl(geocoder);
```

**Webpack alias (if you need it):**

```js
// webpack.config.js
module.exports = {
  // …
  resolve: {
    alias: {
      'mapbox-gl': 'maplibre-gl',
      '@mapbox/mapbox-gl-geocoder': '@maplibre/maplibre-gl-geocoder',
    },
  },
};
```

